 public static function fingerprint(array $v):string{return hash('sha256',json_encode(self::normal($v),JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE));}
 public static function population(array $s):array{
