 private static function accumulated(int $cost,int $years):int{self::money($cost);self::need($years>=0&&$years<=5);return intdiv($cost*$years+2,5);}
 public static function calculate(array $source,array $register,?array $previous=null,int $depth=0):array{
  self::need($depth>=0&&$depth<5);[$cost,$eligible,$excluded]=self::population($source);self::keys($register,['schema','club_id','pool_id','year','opening_cents','depreciation_cents','closing_cents','physical_departures','document','reason','confirmed']);self::need($register['schema']===1&&$register['club_id']===$source['club_id']&&$register['pool_id']===$source['pool_id']&&$register['confirmed']===true);$year=$register['year'];$formed=$source['formed_year'];self::need(is_int($year)&&$year>=$formed&&$year<=$formed+4);self::doc($register['document']);self::note($register['reason']);foreach(['opening_cents','depreciation_cents','closing_cents'] as $k)self::money($register[$k]);$age=$year-$formed;$before=self::accumulated($cost,$age);$after=self::accumulated($cost,$age+1);$opening=$age===0?0:$cost-$before;self::need($register['opening_cents']===$opening&&$register['depreciation_cents']===$after-$before&&$register['closing_cents']===$cost-$after);
