  $fiscal=['cost_opening_cents'=>$age?$cost:0,'additions_cents'=>$age?0:$cost,'cost_closing_cents'=>$cost,'accumulated_opening_cents'=>$before,'depreciation_cents'=>$after-$before,'accumulated_closing_cents'=>$after,'book_opening_cents'=>$opening,'book_closing_cents'=>$cost-$after,'disposals_cents'=>0,'accumulated_disposals_cents'=>0,'book_disposals_cents'=>0];$out=['schema'=>1,'source'=>$source,'register'=>$register,'previous'=>$previous,'fiscal'=>$fiscal,'eligible_items'=>$eligible,'excluded_items'=>$excluded,'departed_items'=>$departed,'journal_verified'=>false,'export_authorized'=>false];return $out+['sha256'=>self::fingerprint($out)];
 }
}
